function firstEven(nums) {
  for (const n of nums) {
    if (n % 2 === 0) return n;
  }
  return undefined;
}

function countPaid(rows) {
  let n = 0;
  for (const row of rows) {
    if (row.status === "paid") n += 1;
  }
  return n;
}
